def _scope_for_job(job):
    params = job.request_params or {}
    region = params.get('region')
    bbox = params.get('bbox') or {}
    if region:
        key = ':'.join(str(region.get(k, '') or '') for k in (
            'country_code', 'type', 'boundary_code', 'name',
        ))
        return 'region', key, {'region': region, 'bbox': bbox}
    if any(value is not None for value in bbox.values()):
        import json
        canonical = json.dumps(bbox, sort_keys=True, separators=(',', ':'))
        return 'bbox', canonical, {'bbox': bbox}
    return 'global', 'world', {'bbox': None, 'region': None}


